CREATE TRIGGER trg_bty_task_start_immutable BEFORE UPDATE ON bty_service_submission
FOR EACH ROW
BEGIN
    IF OLD.action='TASK_START' OR NEW.action='TASK_START' THEN
        IF NOT (NEW.tenant_no <=> OLD.tenant_no) OR NOT (NEW.entity_no <=> OLD.entity_no) OR NOT (NEW.store_no <=> OLD.store_no) OR NOT (NEW.work_order_no <=> OLD.work_order_no) OR NOT (NEW.submission_no <=> OLD.submission_no) OR NOT (NEW.action <=> OLD.action) OR NOT (NEW.request_key_hash <=> OLD.request_key_hash) OR NOT (NEW.payload_hash <=> OLD.payload_hash) OR NOT (NEW.execution_no <=> OLD.execution_no) OR NOT (NEW.frozen_command <=> OLD.frozen_command) OR NOT (NEW.created_at <=> OLD.created_at) OR NOT (NEW.created_by <=> OLD.created_by) OR NOT (NEW.deleted <=> OLD.deleted) OR NEW.version<>OLD.version+1 THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start identity is immutable and version must advance';
        END IF;
        IF NOT (NEW.status=OLD.status OR
            (OLD.status='SOURCE_FROZEN' AND NEW.status IN ('DISPATCHING','ABORT_REQUESTED')) OR
            (OLD.status='DISPATCHING' AND NEW.status IN ('OWNER_ACCEPTED','RESOURCE_APPLIED','ABORT_REQUESTED','RESOURCE_SEALED')) OR
            (OLD.status='OWNER_ACCEPTED' AND NEW.status IN ('RESOURCE_APPLIED','ABORT_REQUESTED','RESOURCE_SEALED')) OR
            (OLD.status='ABORT_REQUESTED' AND NEW.status IN ('RESOURCE_APPLIED','RESOURCE_SEALED')) OR
            (OLD.status='RESOURCE_APPLIED' AND NEW.status='ACKED')) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start phase cannot regress or invent release';
        END IF;
        IF JSON_TYPE(JSON_EXTRACT(OLD.action_observation_json,'$.cancellation'))='OBJECT' AND NOT (JSON_EXTRACT(NEW.action_observation_json,'$.cancellation') <=> JSON_EXTRACT(OLD.action_observation_json,'$.cancellation')) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start original evidence is permanent';
        END IF;
        IF JSON_TYPE(JSON_EXTRACT(OLD.action_observation_json,'$.nativeOriginal.actual'))='OBJECT' AND NOT (JSON_EXTRACT(NEW.action_observation_json,'$.nativeOriginal.actual') <=> JSON_EXTRACT(OLD.action_observation_json,'$.nativeOriginal.actual')) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start original evidence is permanent';
        END IF;
        IF JSON_TYPE(JSON_EXTRACT(OLD.action_observation_json,'$.nativeOriginal.applied'))='OBJECT' AND NOT (JSON_EXTRACT(NEW.action_observation_json,'$.nativeOriginal.applied') <=> JSON_EXTRACT(OLD.action_observation_json,'$.nativeOriginal.applied')) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start original evidence is permanent';
        END IF;
        IF JSON_TYPE(JSON_EXTRACT(OLD.action_observation_json,'$.nativeOriginal.seal'))='OBJECT' AND NOT (JSON_EXTRACT(NEW.action_observation_json,'$.nativeOriginal.seal') <=> JSON_EXTRACT(OLD.action_observation_json,'$.nativeOriginal.seal')) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start original evidence is permanent';
        END IF;
        IF JSON_TYPE(JSON_EXTRACT(OLD.action_observation_json,'$.acknowledgement'))='OBJECT' AND NOT (JSON_EXTRACT(NEW.action_observation_json,'$.acknowledgement') <=> JSON_EXTRACT(OLD.action_observation_json,'$.acknowledgement')) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start original evidence is permanent';
        END IF;
        IF JSON_EXTRACT(OLD.action_observation_json,'$.stopRequired')=true AND JSON_EXTRACT(NEW.action_observation_json,'$.stopRequired')<>true THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start stop is sticky';
        END IF;
    END IF;
END$$

CREATE TRIGGER trg_bty_task_start_no_delete BEFORE DELETE ON bty_service_submission
FOR EACH ROW
BEGIN
    IF OLD.action='TASK_START' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='task start original is permanent';
    END IF;
